// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?
// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id           String        @id @default(cuid())
  email        String        @unique
  passwordHash String
  createdAt    DateTime      @default(now())
  overlays     Overlay[]
  ingestKeys   IngestKey[]
  alertConfigs AlertConfig[]
  alertLogs    AlertLog[]
}

model Overlay {
  id           String   @id @default(cuid())
  userId       String
  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  token        String   @unique
  // A write credential: it authorizes POST /api/control/{controlToken}/fire.
  // Separate from `token` (read-only overlay subscription) so it can be
  // rotated on its own when a dock URL leaks.
  controlToken String   @unique
  name         String   @default("Main")
  createdAt    DateTime @default(now())
}

model IngestKey {
  id         String    @id @default(cuid())
  userId     String
  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  name       String
  hash       String    @unique
  prefix     String
  lastUsedAt DateTime?
  revokedAt  DateTime?
  createdAt  DateTime  @default(now())
}

model EventType {
  key    String @id
  label  String
  fields Json
}

model AlertConfig {
  id            String  @id @default(cuid())
  userId        String
  user          User    @relation(fields: [userId], references: [id], onDelete: Cascade)
  eventTypeKey  String
  enabled       Boolean @default(true)
  template      String
  titleTemplate String?
  style         Json
  durationMs    Int     @default(5000)
  imageUrl      String?
  soundUrl      String?
  soundVolume   Int     @default(80)
  minAmount     Int?
  locale        String  @default("en-US")

  @@unique([userId, eventTypeKey])
}

model AlertLog {
  id           String   @id @default(cuid())
  userId       String
  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  eventTypeKey String
  payload      Json
  renderedText String
  source       String
  deliveredTo  Int      @default(0)
  createdAt    DateTime @default(now())

  @@index([userId, createdAt])
  @@index([createdAt])
}
