import prisma from '@/lib/db';
import { subscribe } from '@/lib/hub';

export const dynamic = 'force-dynamic'; // never cache or prerender a live stream

export async function GET(_req: Request, ctx: { params: Promise<{ token: string }> }) {
  const { token } = await ctx.params;
  const overlay = await prisma.overlay.findUnique({ where: { token } });
  if (!overlay) return Response.json({ error: 'unknown overlay' }, { status: 404 });

  const encoder = new TextEncoder();
  let unsubscribe = () => {};
  let ping: ReturnType<typeof setInterval>;

  const stream = new ReadableStream({
    start(controller) {
      const push = (frame: string) => controller.enqueue(encoder.encode(frame));
      push(': connected\n\n');
      unsubscribe = subscribe(overlay.userId, push);
      // Keeps intermediary proxies from idling the connection out.
      ping = setInterval(() => {
        try {
          push(': ping\n\n');
        } catch {
          clearInterval(ping);
          unsubscribe();
        }
      }, 15_000);
    },
    cancel() {
      clearInterval(ping);
      unsubscribe();
    },
  });

  return new Response(stream, {
    headers: {
      'content-type': 'text/event-stream; charset=utf-8',
      'cache-control': 'no-store, no-transform',
      connection: 'keep-alive',
      'x-accel-buffering': 'no', // nginx: do not buffer this response
    },
  });
}
import { handleControlFire } from '@/lib/controlFire';

export async function POST(req: Request, ctx: { params: Promise<{ token: string }> }) {
  const { token } = await ctx.params;
  return handleControlFire(req, token);
}
// The shared shape of a send result, formatted the same way by every editor
// that reports one (Editor.tsx, ResultEditor.tsx) so the wording cannot drift.
export function describeResult(r: { status: number; body: unknown }): string {
  if (r.status === 200) {
    const b = r.body as { delivered: number };
    return `200 — delivered to ${b.delivered} overlay connection(s)`;
  }
  if (r.status === 202) {
    const b = r.body as { skipped: string };
    return `202 — skipped: ${b.skipped}`;
  }
  // The real status, not a hardcoded 400: the control dock also sees 401, 413,
  // 429 and 500. Identical output for the dashboard's only failure case.
  return `${r.status} — ${(r.body as { error: string }).error}`;
}
